.pc-header-block__title.pc-header-block__title {
  margin: 0;
}

/* use this for style redefinitions to awoid problems with
unpredictable css rules order in build */
.pc-header-block {
  position: relative;
}
.pc-header-block_full-width {
  --pc-border-radius: 0;
  padding: 16px 0;
  margin: 0 0 16px;
}
.pc-header-block__content-wrapper {
  margin: 0 8px;
  height: 100%;
}
.pc-header-block__content {
  position: relative;
  height: 100%;
}
.pc-header-block__content_theme_dark.pc-header-block__content_theme_dark {
  --g-color-line-focus: var(--pc-color-line-focus-dark);
}
.pc-header-block__content_theme_dark.pc-header-block__content_theme_dark .pc-header-block__title {
  color: var(--g-color-text-light-primary);
}
.pc-header-block__content_theme_dark.pc-header-block__content_theme_dark .pc-header-block__description .yfm,
.pc-header-block__content_theme_dark.pc-header-block__content_theme_dark .pc-header-block__overtitle .yfm {
  color: var(--g-color-text-light-primary);
}

.pc-header-block__content_theme_dark .pc-header-block__additional-info .yfm p {
  color: var(--g-color-text-light-secondary) !important; /* stylelint-disable-line declaration-no-important */
}
.pc-header-block__content_vertical-offset {
  margin: 16px 0;
}
.pc-header-block__content_vertical-offset_s {
  padding: 64px 0;
}
.pc-header-block__content_vertical-offset_m {
  padding: 96px 0;
}
.pc-header-block__content_vertical-offset_l {
  padding: 128px 0;
}
.pc-header-block__content_vertical-offset_xl {
  padding: 160px 0;
}
.pc-header-block__content_offset_large {
  padding: calc(128px - 16px) 0 16px;
}
.pc-header-block__content-outer, .pc-header-block__content-inner {
  position: relative;
  z-index: 10;
}
.pc-header-block__content-inner_centered {
  margin-inline: auto;
  text-align: center;
}
.pc-header-block__title.pc-header-block__title {
  font-size: var(--g-text-display-4-font-size);
  line-height: var(--g-text-display-4-line-height);
  color: var(--pc-text-header-color);
  font-weight: var(--g-text-accent-font-weight);
  position: relative;
}
@media (max-width: 769px) {
  .pc-header-block__title.pc-header-block__title {
    font-size: var(--g-text-display-3-font-size);
    line-height: var(--g-text-display-3-line-height);
  }
}
@media (max-width: 577px) {
  .pc-header-block__title.pc-header-block__title {
    font-size: var(--g-text-display-2-font-size);
    line-height: var(--g-text-display-2-line-height);
  }
}
.pc-header-block__title.pc-header-block__title a {
  outline: none;
  color: var(--g-color-text-link);
  text-decoration: none;
  cursor: pointer;
}
.utilityfocus .pc-header-block__title.pc-header-block__title a:focus {
  outline: 2px solid #ffdb4d;
}
.pc-header-block__title.pc-header-block__title a:hover, .pc-header-block__title.pc-header-block__title a:active {
  --pc-text-header-color: var(--g-color-text-link-hover);
  color: var(--g-color-text-link-hover);
}

.pc-header-block__title-container {
  margin: 0;
}
.pc-header-block__description {
  margin-top: 16px;
}
.pc-header-block__description .yfm {
  font-size: var(--g-text-body-3-font-size);
  line-height: var(--g-text-body-3-line-height);
  color: var(--g-color-text-primary);
}
.pc-header-block__additional-info {
  margin-top: 16px;
}
.pc-header-block__additional-info .yfm p {
  font-size: var(--g-text-body-2-font-size);
  line-height: var(--g-text-body-2-line-height);
  color: var(--g-color-text-secondary) !important; /* stylelint-disable-line declaration-no-important */
}
.pc-header-block__buttons {
  margin-top: 16px;
}
.pc-header-block__button.pc-header-block__button {
  margin-top: 16px;
}
.pc-header-block__button.pc-header-block__button:not(:last-child) {
  margin-right: 12px;
}

.pc-header-block__media {
  position: absolute;
  display: none;
  top: 16px;
  right: 0;
  width: 50%;
  height: calc(100% - 2 * 16px);
  overflow: hidden;
  object-fit: cover;
  border-radius: var(--pc-border-radius);
}
.pc-header-block__media_s {
  width: 32%;
}
.pc-header-block__video {
  height: 100%;
}
.pc-header-block__video > video {
  border-radius: var(--pc-border-radius);
  width: 100%;
  height: 100%;
  object-fit: cover;
}
.pc-header-block__image {
  width: 100%;
  height: 100%;
  object-fit: cover;
  border-radius: var(--pc-border-radius);
}
.pc-header-block__video-iframe {
  position: absolute;
  top: 50%;
  right: 0;
  left: 0;
  transform: translateY(-50%);
}
.pc-header-block__breadcrumbs {
  position: absolute;
  top: 16px;
  z-index: 11;
}
.pc-header-block__background-media {
  height: 100%;
}
.pc-header-block__background-media > div {
  height: 100%;
  width: 100%;
}
.pc-header-block__background-media > div:not(.pc-header-block__video) {
  position: absolute;
}
.pc-header-block__background, .pc-header-block__background.pc-header-block__background_media {
  position: absolute;
  top: 0;
  overflow: hidden;
  z-index: 5;
  width: 1440px;
  max-width: 100%;
  left: 50%;
  transform: translateX(-50%);
  height: 100%;
  border-radius: var(--pc-border-radius);
}
.pc-header-block__background.pc-header-block__background_full-width-media, .pc-header-block__background.pc-header-block__background_media.pc-header-block__background_full-width-media {
  width: 100%;
}
